<?php require __DIR__.'/guard.php'; ?>
<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Паспорт техники — ПрофиСпорт</title>
<style>
:root{--y:#f2c94c;--bg:#f5f5f3;--tx:#202124;--muted:#747a80;--line:#e3e3df;--green:#1f7a3e;--orange:#ba6a16;--red:#a53f35;--page:1240px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}button,input,select,textarea{font:inherit}.top{position:sticky;top:0;z-index:30;background:#34393e;color:#fff}.topin{max-width:var(--page);margin:auto;min-height:62px;padding:0 14px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:20px;font-weight:950}.brand span{color:var(--y)}.back{color:#fff;text-decoration:none;padding:9px 12px;border:1px solid #ffffff25;border-radius:10px}main{max-width:var(--page);margin:auto;padding:18px 14px 70px}.hero,.panel{background:#fff;border:1px solid var(--line);border-radius:18px}.hero{padding:18px}.hero h1{margin:0 0 5px;font-size:28px}.meta{color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(360px,.85fr);gap:14px;margin-top:14px}.panel{padding:16px}.panel h2{margin:0 0 10px}.vehicleDiagram{position:relative;max-width:720px;margin:auto;border-radius:16px;background:#faf9f5;overflow:hidden}.vehicleDiagram img{display:block;width:100%;height:auto}.hotspot{position:absolute;transform:translate(-50%,-50%);width:30px;height:30px;border:4px solid #fff;border-radius:50%;background:#a8aaad;box-shadow:0 2px 8px #0004;font-size:11px;font-weight:950;cursor:pointer}.hotspot.good{background:#39a35c}.hotspot.watch{background:#e4bd35}.hotspot.soon{background:#e38226}.hotspot.due{background:#c94c3d}.hotspot.selected{outline:3px solid #2228;outline-offset:2px}.legend{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.legend span{padding:5px 8px;border-radius:999px;background:#eee;font-size:11px}.componentList{display:grid;gap:8px;margin-top:12px}.componentItem{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:11px;border:1px solid var(--line);border-radius:12px;background:#faf9f5;cursor:pointer}.componentItem b,.componentItem span{display:block}.componentItem .wear{font-weight:950}.componentItem[data-state=good] .wear{color:var(--green)}.componentItem[data-state=watch] .wear{color:#9a7b00}.componentItem[data-state=soon] .wear{color:var(--orange)}.componentItem[data-state=due] .wear{color:var(--red)}.editor{display:grid;gap:11px}.editorGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.editor label,.vehicleFacts label{display:grid;gap:5px;font-weight:800}.editor input,.editor select,.editor textarea,.vehicleFacts input{width:100%;min-width:0;padding:9px;border:1px solid var(--line);border-radius:9px;background:#fff}.wide{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{border:0;border-radius:10px;padding:10px 13px;font-weight:900;background:var(--y)}.actions .secondary{background:#e8e9e6}.actions .danger{background:#f4e3e0;color:#8c3027}.eventBox{border-top:1px solid var(--line);padding-top:13px;margin-top:3px}.eventList{display:grid;gap:6px;max-height:240px;overflow:auto}.eventRow{padding:8px;border-radius:9px;background:#f7f7f4}.sourceState{padding:10px;border-radius:11px;background:#f7f7f4}.sourceState.verified{background:#e7f6eb;color:#176f38}.wearCard{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.wearCard div{padding:10px;border-radius:11px;background:#f7f7f4}.wearCard b{display:block;font-size:17px}.wearCard span{display:block;color:var(--muted);font-size:10px}.vehicleFacts{display:grid;grid-template-columns:1fr 1fr auto;gap:9px;align-items:end}.vehicleFacts button{min-height:39px;border:0;border-radius:9px;background:var(--y);font-weight:900}.notice{min-height:20px;color:var(--muted)}.empty{padding:14px;border:1px dashed #d8d4ca;border-radius:12px;color:var(--muted)}
@media(max-width:900px){.layout{grid-template-columns:1fr}.vehicleFacts{grid-template-columns:1fr 1fr}.vehicleFacts button{grid-column:1/-1}.editorGrid{grid-template-columns:1fr}.wide{grid-column:auto}}@media(max-width:520px){main{padding:12px 10px 60px}.vehicleFacts{grid-template-columns:1fr}.wearCard{grid-template-columns:1fr}}
</style></head><body>
<header class="top"><div class="topin"><div class="brand">Профи<span>Спорт</span> · Паспорт техники</div><a class="back" href="customers.php">← Клиенты</a></div></header>
<main><section class="hero"><h1 id="vehicleTitle">Загрузка…</h1><div id="vehicleMeta" class="meta"></div><div class="vehicleFacts"><label>Серийный номер<input id="serialNumber" maxlength="180"></label><label>Пробег, км<input id="odometer" type="number" min="0" step="0.1"></label><button id="saveVehicle">Сохранить данные</button></div><div id="vehicleMsg" class="notice"></div></section>
<div class="layout">
<section class="panel"><h2>Интерактивная схема</h2><div id="diagramArea"></div><div id="componentList" class="componentList"></div></section>
<section class="panel"><h2 id="editorTitle">Компонент</h2><div id="componentEditor"></div></section>
</div></main>
<script>
let csrf='',passport=null,selectedId=0;const vehicleId=Number(new URLSearchParams(location.search).get('id')||0);const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const dt=v=>v?new Date(String(v).replace(' ','T')).toLocaleString('ru-RU'):'—';
async function req(data){const r=await fetch('../api/vehicle-passport-admin.php',{method:data? 'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'server_error');if(j.csrf)csrf=j.csrf;return j}
function stateLabel(w){if(!w||w.percent===null)return 'Нет расчёта';return Number(w.percent).toLocaleString('ru-RU',{maximumFractionDigits:1})+'%'}
function remaining(w){if(!w||w.remaining===null)return '';return w.unit==='days'?' · осталось ~'+Math.round(w.remaining)+' дн.':w.unit==='km'?' · осталось ~'+Math.round(w.remaining)+' км':''}
function sourceLabel(c){return c.source_type==='official'?'Официальный источник':c.source_type==='1c_spec'?'Карточка 1С':c.source_type==='service'?'Подтверждено сервисом':'Внесено вручную'}
function hotspotState(key){
 const list=passport.components.filter(c=>c.hotspot_key===key&&c.wear?.percent!==null);if(!list.length)return 'unknown';
 const max=list.reduce((a,c)=>Number(c.wear.percent)>Number(a.wear.percent)?c:a,list[0]);return max.wear.state||'unknown';
}
function render(){
 const v=passport.vehicle,verified=passport.verified_profile;$('#vehicleTitle').textContent=v.title;$('#vehicleMeta').innerHTML='Заказ '+esc(v.order_number||'—')+' · покупка '+esc(dt(v.purchase_date||v.created_at))+' · клиент #'+Number(v.customer_id)+(verified?' · <a href="'+esc(verified.source_url)+'" target="_blank" rel="noopener">официальный профиль '+esc(verified.key)+' ✓</a>':' · официальная спецификация не сопоставлена');$('#serialNumber').value=v.serial_number||'';$('#odometer').value=v.odometer_km??'';
 $('#diagramArea').innerHTML=passport.vehicle.vehicle_type==='bicycle'
   ?'<div class="vehicleDiagram"><img src="../assets/guide/bicycle.png" width="1382" height="1130" alt="Схема велосипеда"><div id="hotspots">'+passport.hotspots.map((h,i)=>'<button class="hotspot '+hotspotState(h.key)+'" style="left:'+h.x+'%;top:'+h.y+'%" data-hotspot="'+esc(h.key)+'" title="'+esc(h.label)+'">'+(i+1)+'</button>').join('')+'</div></div><div class="legend"><span>🟢 ресурс большой</span><span>🟡 обратить внимание</span><span>🟠 скоро обслуживание</span><span>🔴 расчётный ресурс исчерпан</span><span>⚪ нет достоверного расчёта</span></div>'
   :'<div class="empty"><b>Схема этого типа техники пока не настроена.</b><br>Компоненты можно вести как паспорт без ложной велосипедной картинки.</div>';
 $('#componentList').innerHTML=passport.components.length?passport.components.map(c=>'<article class="componentItem" data-component="'+c.id+'" data-state="'+esc(c.wear?.state||'unknown')+'"><div><b>'+esc(c.label)+'</b><span class="meta">'+esc([c.manufacturer,c.model].filter(Boolean).join(' ')||'Точная модель не подтверждена')+'</span></div><div><span class="wear">'+stateLabel(c.wear)+'</span><span class="meta">'+esc(sourceLabel(c))+'</span></div></article>').join(''):'<div class="empty">Из 1С точная комплектация не извлечена. Добавьте подтверждённые узлы вручную или укажите официальный источник.</div>';
 document.querySelectorAll('[data-component]').forEach(x=>x.onclick=()=>selectComponent(Number(x.dataset.component)));
 document.querySelectorAll('[data-hotspot]').forEach(x=>x.onclick=()=>{const c=passport.components.find(z=>z.hotspot_key===x.dataset.hotspot);if(c)selectComponent(c.id);else newComponent(x.dataset.hotspot)});
 if(selectedId&&passport.components.some(c=>c.id===selectedId))selectComponent(selectedId,false);else newComponent(passport.hotspots[0]?.key||'general',false);
}
function editorMarkup(c){
 const w=c?.wear||{},events=c?.events||[],isNew=!c;
 return '<div class="editor"><div class="wearCard"><div><span>Расчётный износ</span><b>'+stateLabel(w)+'</b></div><div><span>Прогноз ресурса</span><b>'+(w.predicted_life!==null&&w.predicted_life!==undefined?esc(String(w.predicted_life))+' '+(w.unit==='days'?'дн.':w.unit==='km'?'км':''):'—')+'</b></div><div><span>Персональных циклов</span><b>'+Number(w.personal_samples||0)+'</b></div></div>'+
 '<div class="sourceState '+(c?.source_verified_at?'verified':'')+'"><b>'+(c?.source_verified_at?'Источник подтверждён':'Источник требует проверки')+'</b><div class="meta">'+esc(c?sourceLabel(c):'Новый компонент')+(c?.source_url?' · '+esc(c.source_url):'')+'</div></div>'+
 '<form id="componentForm" class="editorGrid"><input type="hidden" name="id" value="'+Number(c?.id||0)+'"><label>Ключ компонента<input name="component_key" required value="'+esc(c?.component_key||'')+'" placeholder="front_brake_pads"></label><label>Зона<select name="hotspot_key"><option value="general" '+(c?.hotspot_key==='general'?'selected':'')+'>Общий узел</option>'+passport.hotspots.map(h=>'<option value="'+esc(h.key)+'" '+(c?.hotspot_key===h.key?'selected':'')+'>'+esc(h.label)+'</option>').join('')+'</select></label><label class="wide">Название для клиента<input name="label" required value="'+esc(c?.label||'')+'" placeholder="Передние тормозные колодки"></label><label>Производитель<input name="manufacturer" value="'+esc(c?.manufacturer||'')+'"></label><label>Модель<input name="model" value="'+esc(c?.model||'')+'"></label><label>Источник<select name="source_type"><option value="1c_spec" '+(c?.source_type==='1c_spec'?'selected':'')+'>1С</option><option value="official" '+(c?.source_type==='official'?'selected':'')+'>Официальный источник</option><option value="service" '+(c?.source_type==='service'?'selected':'')+'>Сервис</option><option value="manual" '+(!c||c?.source_type==='manual'?'selected':'')+'>Вручную</option></select></label><label>Ссылка на источник<input name="source_url" type="url" value="'+esc(c?.source_url||'')+'"></label><label class="wide">Комментарий к источнику<input name="source_note" value="'+esc(c?.source_note||'')+'"></label><label class="wide"><span><input name="source_verified" type="checkbox" '+(c?.source_verified_at?'checked':'')+'> источник проверен администратором</span></label>'+
 '<label>Расчёт ресурса<select name="wear_mode"><option value="inspection">Только осмотр</option><option value="time" '+(c?.wear_mode==='time'?'selected':'')+'>По времени</option><option value="distance" '+(c?.wear_mode==='distance'?'selected':'')+'>По пробегу</option><option value="measurement" '+(c?.wear_mode==='measurement'?'selected':'')+'>По замеру</option></select></label><label>Базовый ресурс<input name="baseline_life_value" type="number" min="0" step="0.1" value="'+esc(c?.baseline_life_value??'')+'" placeholder="Только если подтверждён"></label><label>Единица базового ресурса<select name="baseline_life_unit"><option value="">—</option><option value="days" '+(c?.baseline_life_unit==='days'?'selected':'')+'>дни</option><option value="km" '+(c?.baseline_life_unit==='km'?'selected':'')+'>км</option></select></label><label>Установлен<input name="installed_at" type="datetime-local" value="'+esc(String(c?.installed_at||'').replace(' ','T').slice(0,16))+'"></label>'+
 '<label>Начальный замер<input name="baseline_measurement" type="number" step="0.001" value="'+esc(c?.baseline_measurement??'')+'"></label><label>Порог замены<input name="replacement_threshold" type="number" step="0.001" value="'+esc(c?.replacement_threshold??'')+'"></label><label>Единица замера<input name="measurement_unit" value="'+esc(c?.measurement_unit||'')+'" placeholder="мм, %, В..."></label><label>Износ идёт<select name="measurement_direction"><option value="">—</option><option value="down" '+(c?.measurement_direction==='down'?'selected':'')+'>значение уменьшается</option><option value="up" '+(c?.measurement_direction==='up'?'selected':'')+'>значение растёт</option></select></label><label>Совместимый товар ID<input name="compatible_product_id" type="number" min="1" value="'+esc(c?.compatible_product_id??'')+'"></label><div class="actions wide"><button type="submit">Сохранить компонент</button>'+(isNew?'':'<button id="removeComponent" type="button" class="danger">Убрать компонент</button>')+'</div></form>'+
 (isNew?'':'<div class="eventBox"><h3>Записать событие</h3><form id="eventForm" class="editorGrid"><label>Тип<select name="event_type"><option value="replaced">Замена</option><option value="measured">Замер</option><option value="inspected">Осмотр</option><option value="installed">Установка</option></select></label><label>Дата<input name="event_at" type="datetime-local" value="'+new Date().toISOString().slice(0,16)+'"></label><label>Пробег, км<input name="odometer_km" type="number" min="0" step="0.1"></label><label>Значение замера<input name="measurement_value" type="number" step="0.001"></label><label>Единица<input name="measurement_unit" placeholder="мм, %, ..."></label><label class="wide"><span><input name="include_learning" type="checkbox" checked> учитывать цикл в персональном прогнозе</span></label><label class="wide">Комментарий<textarea name="note" rows="2"></textarea></label><div class="actions wide"><button type="submit">Записать событие</button></div></form><h3>История</h3><div class="eventList">'+(events.length?events.map(e=>'<div class="eventRow"><b>'+esc(e.event_type)+'</b> · '+dt(e.event_at)+(e.odometer_km!==null?' · '+esc(e.odometer_km)+' км':'')+(e.measurement_value!==null?' · '+esc(e.measurement_value)+' '+esc(e.measurement_unit||''):'')+(Number(e.include_learning)?'':' · не обучает')+(e.note?'<div class="meta">'+esc(e.note)+'</div>':'')+'</div>').join(''):'<div class="empty">Событий пока нет.</div>')+'</div></div>')+'</div>';
}
function bindEditor(c){
 const form=$('#componentForm');form.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(form));x.id=Number(x.id||0);x.source_verified=form.elements.source_verified.checked;x.compatible_product_id=x.compatible_product_id?Number(x.compatible_product_id):null;for(const k of ['baseline_life_value','baseline_measurement','replacement_threshold'])x[k]=x[k]!==''?Number(x[k]):null;x.installed_at=x.installed_at?x.installed_at.replace('T',' ')+':00':null;try{const j=await req({action:'save_component',vehicle_id:vehicleId,component:x});passport=j.passport;selectedId=j.component.id;render()}catch(err){alert('Не удалось сохранить компонент: '+err.message)}};
 $('#removeComponent')?.addEventListener('click',async()=>{if(!confirm('Убрать компонент из паспорта?'))return;const j=await req({action:'remove_component',vehicle_id:vehicleId,component_id:c.id});passport=j.passport;selectedId=0;render()});
 const ef=$('#eventForm');if(ef)ef.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(ef));x.include_learning=ef.elements.include_learning.checked;x.event_at=x.event_at?x.event_at.replace('T',' ')+':00':null;for(const k of ['odometer_km','measurement_value'])x[k]=x[k]!==''?Number(x[k]):null;try{const j=await req({action:'record_event',vehicle_id:vehicleId,component_id:c.id,event:x});passport=j.passport;render()}catch(err){alert('Не удалось записать событие: '+err.message)}};
}
function selectComponent(id,scroll=true){selectedId=id;const c=passport.components.find(x=>x.id===id);if(!c)return;$('#editorTitle').textContent=c.label;$('#componentEditor').innerHTML=editorMarkup(c);bindEditor(c);document.querySelectorAll('.hotspot').forEach(x=>x.classList.toggle('selected',x.dataset.hotspot===c.hotspot_key));if(scroll&&innerWidth<900)$('#componentEditor').scrollIntoView({behavior:'smooth',block:'start'})}
function newComponent(hotspot,scroll=true){selectedId=0;const h=passport.hotspots.find(x=>x.key===hotspot);$('#editorTitle').textContent='Новый компонент';$('#componentEditor').innerHTML=editorMarkup({hotspot_key:hotspot,label:h?.label||'',component_key:'',source_type:'manual',wear_mode:'inspection',events:[],wear:{percent:null,personal_samples:0}});bindEditor(null);if(scroll&&innerWidth<900)$('#componentEditor').scrollIntoView({behavior:'smooth',block:'start'})}
$('#saveVehicle').onclick=async()=>{try{const j=await req({action:'save_vehicle',vehicle_id:vehicleId,serial_number:$('#serialNumber').value.trim(),odometer_km:$('#odometer').value!==''?Number($('#odometer').value):null});passport=j.passport;$('#vehicleMsg').textContent='Данные сохранены.';render()}catch(e){$('#vehicleMsg').textContent='Ошибка сохранения.'}};
(async()=>{if(vehicleId<1){$('#vehicleTitle').textContent='Не указан велосипед';return}const a=await fetch('../server/api.php?action=me',{cache:'no-store'});if(!a.ok){location.href='index.php';return}csrf=(await a.json()).csrf||'';try{const j=await fetch('../api/vehicle-passport-admin.php?vehicle_id='+vehicleId,{cache:'no-store'}).then(async r=>{const x=await r.json();if(!r.ok)throw new Error(x.error);return x});passport=j.passport;render()}catch(e){$('#vehicleTitle').textContent='Не удалось открыть паспорт техники'}})();
</script></body></html>